class Solution {
    private int gcd(int a,int b){
        while(b!=0){
            int next=a%b;
            a=b;
            b=next;
        }
        return a;
    }
    public ListNode insertGreatestCommonDivisors(ListNode head){
        ListNode node=head;
        while(node.next!=null){
            ListNode next=node.next;
            node.next=new ListNode(gcd(node.val,next.val),next);
            node=next;
        }
        return head;
    }
}

code.kotlin:
class Solution {
    private fun gcd(aInput:Int,bInput:Int):Int{
        var a=aInput;
        var b=bInput;
        while(b!=0){
            val next=a%b;
            a=b;
            b=next
        };
        return a
    };
    fun insertGreatestCommonDivisors(head:ListNode?):ListNode?{
        var node=head;
        while(node?.next!=null){
            val next=node.next!!;
            val inserted=ListNode(gcd(node.`val`,next.`val`));
            inserted.next=next;
            node.next=inserted;
            node=next
        };
        return head
    }
}

